import {b,fmt,clamp,shells,heating,work,buoyancy,pendulum,falling} from '../math.js';
import {C,reflect,read,particles,molecule,atom,cell,neuron,plants,organelles} from '../scene-utils.js';
export default ({g,t,p})=>{let h=p[0],duration=Math.sqrt(2*h/10),data=falling(h,t%(duration+.6)),y=-.85+1.7*(1-data.height/h);g.sphere(-.4,y,0,.13,C.gold);g.line([-1,.97,0],[.3,.97,0]);g.bars({title:b('Energy conversion (2 kg, g = 10)','ऊर्जा परिवर्तन (2 kg, g = 10)'),max:data.total,items:[{label:b('KE','गतिज'),value:data.ke,color:C.blue},{label:b('PE','स्थितिज'),value:data.pe,color:C.green},{label:b('Total','कुल'),value:data.total,color:C.gold}]});return[read('Height remaining','शेष ऊँचाई',fmt(data.height),'m'),read('Speed','चाल',fmt(data.v),'m/s'),read('Total energy','कुल ऊर्जा',data.total,'J')];};
